/bin/bash -lc "cat /etc/resolv.conf || true
python3 - <<'PY'
import socket
for host in [\"api.openai.com\", \"developers.openai.com\", \"platform.openai.com\"]:
    try:
        print(host, socket.getaddrinfo(host, 443))
    except Exception as exc:
        print(host, type(exc).__name__, exc)
PY
curl -I --max-time 10 --silent --show-error https://1.1.1.1 || true"

